        breeds: [{ id: 'person', count: 'round(density*size*size)', place: 'empty', vars: { group: { init: 'rnd < fracA ? 0 : 1', type: 'cat', n: 2 } },
          rules: [{ do: 'move', how: 'jump', when: 'nb > 0 && same/nb < want', act: 'moved' }] }],
        aggregates: [{ id: 'same', of: 'neighbours', fn: 'count', where: 'group == my_group' }, { id: 'nb', of: 'neighbours', fn: 'count' }],
        reporters: [{ id: 'similar', fn: 'mean', expr: 'same/nb', where: 'nb > 0' }, { id: 'unhappy', fn: 'frac', where: 'nb > 0 && same/nb < want' }, { id: 'agents', fn: 'count' }],
