          db.push(lc); st.learned++; E({ k: 'learn', c: db.length - 1, lits: lc, lvl: dl });
          const back = lc.reduce((m, l) => (level[Math.abs(l)] < dl ? Math.max(m, level[Math.abs(l)]) : m), 0);
