      const D = [['may', 15], ['may', 16], ['may', 19], ['june', 17], ['june', 18], ['july', 14], ['july', 16], ['august', 14], ['august', 15], ['august', 17]];
      const worlds = D.map(([m, d]) => ({ id: m + d, holds: [m, 'd' + d, m + d] }));
