    const refl = system === 'T' || system === 'S4', trans = system === 'K4' || system === 'S4', serial = system === 'D' || refl;
    const ev = []; let nodes = 0, worlds = 0, over = false;
    const E = e => { if (ev.length < MAX_EVENTS) ev.push(e); else D.add('trace-truncated'); };
    const K = f => key(f);
