  const langOf = m => (m.task === 'normal-form' && FOL_FORMS.includes(m.form) ? 'fol' : LANG_OF[m.task] || 'prop');
  const ATOM_TASKS = ['truth-table', 'equivalent', 'entails', 'many-valued', 'io'];
