    const p2 = Math.asin(Math.sin(p1) * Math.cos(arc) + Math.cos(p1) * Math.sin(arc) * Math.cos(a));
    const l2 = lo * D2R + Math.atan2(Math.sin(a) * Math.sin(arc) * Math.cos(p1), Math.cos(arc) - Math.sin(p1) * Math.sin(p2));
